/**
 * Route country verdict combination and unknown-identity parity with the
 * reference engine (guard_core/core/checks/helpers.py `check_route_ip_access`,
 * guard_core/_utils/access_control.py `_check_unknown_identity_access`): a
 * blocked verdict from either the route IP lists or the route countries
 * denies, an allowed verdict from either allows, otherwise no verdict; the
 * unknown client identity is allowed unless a whitelist or country whitelist
 * is configured. The expectations in ip-list-route-country-cases.json are
 * generated by running the reference.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { isIpAllowed } from '../../src/utils.js';
import { checkIpAccess } from '../../src/core/checks/ip-access.js';
import { checkRouteIpAccess } from '../../src/core/checks/helpers.js';
import { SecurityConfigSchema } from '../../src/models/config.js';
import { RouteConfig } from '../../src/models/route-config.js';
import type { GeoIPHandler } from '../../src/protocols/geo-ip.js';
import { createMockMiddleware } from '../helpers.js';

interface Cases {
  countries: Record<string, string | null>;
  route: Array<{
    routeWhitelist: string[];
    routeBlacklist: string[];
    blockedCountries: string[];
    whitelistCountries: string[];
    ip: string;
    route: boolean | null;
  }>;
  global: Array<{ whitelist: string[]; whitelistCountries: string[]; ip: string; allowed: boolean }>;
}

const CASES: Cases = JSON.parse(
  readFileSync(new URL('./ip-list-route-country-cases.json', import.meta.url), 'utf8'),
);

const geo = {
  isInitialized: true,
  async initialize() {},
  getCountry: (ip: string) => CASES.countries[ip] ?? null,
} as unknown as GeoIPHandler;

describe('route IP lists and countries combine like the reference', () => {
  it.each(CASES.route.map((r) => [JSON.stringify(r), r] as const))('%s', async (_l, r) => {
    const rc = new RouteConfig();
    rc.ipWhitelist = r.routeWhitelist.length > 0 ? r.routeWhitelist : null;
    rc.ipBlacklist = r.routeBlacklist.length > 0 ? r.routeBlacklist : null;
    rc.blockedCountries = r.blockedCountries;
    rc.whitelistCountries = r.whitelistCountries;
    const mw = { ...createMockMiddleware(), geoIpHandler: geo };
    expect(await checkRouteIpAccess(r.ip, rc, mw)).toBe(r.route);
  });
});

describe('global access with country whitelist matches the reference', () => {
  const cfg = (r: Cases['global'][number]) =>
    SecurityConfigSchema.parse({
      enableRedis: false,
      whitelist: r.whitelist.length > 0 ? r.whitelist : null,
      whitelistCountries: r.whitelistCountries,
      geoIpHandler: geo,
    });

  it.each(CASES.global.map((r) => [JSON.stringify(r), r] as const))('checkIpAccess %s', async (_l, r) => {
    expect((await checkIpAccess(r.ip, cfg(r), geo)).allowed).toBe(r.allowed);
  });

  it.each(CASES.global.map((r) => [JSON.stringify(r), r] as const))('isIpAllowed %s', async (_l, r) => {
    expect(await isIpAllowed(r.ip, cfg(r), geo)).toBe(r.allowed);
  });
});
